<?php /** @var array $records */ /** @var array $summary */ ?>
<div class="page-header"><div><h1>My work activity</h1><p class="subtitle">Review the website activity collected during your scheduled work hours.</p></div></div>
<div class="row g-3 mb-3"><?php foreach ([['Focus time', $summary['productive_minutes'] ?? 0, 'sparkles'], ['Neutral time', $summary['neutral_minutes'] ?? 0, 'minus-circle'], ['Distraction time', $summary['distracting_minutes'] ?? 0, 'triangle-alert']] as [$label, $value, $icon]): ?><div class="col-4"><div class="metric-card"><div class="metric-icon"><i data-lucide="<?= $icon ?>"></i></div><div class="metric-label"><?= e($label) ?></div><div class="metric-value"><?= e((string) $value) ?> min</div></div></div><?php endforeach; ?></div>
<div class="card"><div class="card-header">Recent activity</div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Domain</th><th>Category</th><th>Time</th><th>Duration</th><th>Action</th></tr></thead><tbody><?php foreach ($records['data'] as $row): ?><tr><td><strong><?= e($row['domain']) ?></strong></td><td><?= status_badge($row['category']) ?></td><td><?= e($row['started_at']) ?></td><td><?= e((string) round(((int) $row['duration_seconds']) / 60, 1)) ?> min</td><td><?php if (in_array($row['category'], ['distracting','blocked'], true) && !empty($row['distraction_event_id'])): ?><button class="btn btn-sm btn-soft" data-bs-toggle="modal" data-bs-target="#dispute<?= (int) $row['id'] ?>">Explain</button><div class="modal fade" id="dispute<?= (int) $row['id'] ?>" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><form method="post" action="/employee/monitoring/activity/disputes"><?= csrf_field() ?><div class="modal-header"><h5 class="modal-title">Explain this activity</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="event_id" value="<?= (int) $row['distraction_event_id'] ?>"><p class="small text-muted">Explain why <?= e($row['domain']) ?> was needed for work.</p><textarea class="form-control" name="reason" rows="4" required></textarea></div><div class="modal-footer"><button class="btn btn-primary">Submit explanation</button></div></form></div></div></div><?php endif; ?></td></tr><?php endforeach; ?><?php if (empty($records['data'])): ?><tr><td colspan="5" class="text-center text-muted py-5">No website activity has been recorded yet.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card mt-3"><div class="card-header">Request a training or research exception</div><div class="card-body"><form method="post" action="/employee/monitoring/activity/exceptions" class="row g-2"><?= csrf_field() ?><div class="col-md-3"><input class="form-control" name="domain" placeholder="youtube.com" required></div><div class="col-md-3"><select class="form-select" name="context"><option value="training">Training</option><option value="research">Research</option></select></div><div class="col-md-5"><input class="form-control" name="reason" placeholder="Why is this needed for work?" required></div><div class="col-md-1"><button class="btn btn-soft w-100">Request</button></div></form></div></div>
